UPDATE `external_session`
SET `facet` = json_set(`facet`, '$.presentation', json(CASE json_extract(`facet`, '$.name')
  WHEN 'claude-code' THEN '{"label":"Claude Code","iconProvider":"claude-code","mark":"<svg width=\"24\" height=\"24\" viewBox=\"0 0 16 16\" fill=\"none\" shape-rendering=\"crispEdges\" xmlns=\"http://www.w3.org/2000/svg\">\n<path fill-rule=\"evenodd\" d=\"M2 3h12v7H2zM0 5h2v2H0zM14 5h2v2h-2zM3 10h1v3H3zM5 10h1v3H5zM10 10h1v3h-1zM12 10h1v3h-1zM5 5h1v2H5zM10 5h1v2h-1z\" fill=\"currentColor\"/>\n</svg>","install":"curl -fsSL https://claude.ai/install.sh | bash","modelProvider":"claude-code","terminal":true,"acp":true,"hosted":true,"sharedSessions":true}'
  WHEN 'codex' THEN '{"label":"Codex","iconProvider":"codex","mark":null,"install":"npm install -g @openai/codex","modelProvider":"codex","terminal":true,"acp":false,"hosted":false,"sharedSessions":true}'
  WHEN 'grok' THEN '{"label":"Grok Build","iconProvider":"xai","mark":null,"install":null,"modelProvider":null,"terminal":true,"acp":false,"hosted":false,"sharedSessions":true}'
  WHEN 'devin' THEN '{"label":"Devin","iconProvider":"devin","mark":null,"install":null,"modelProvider":"devin","terminal":true,"acp":true,"hosted":false,"sharedSessions":true}'
  WHEN 'cursor' THEN '{"label":"Cursor","iconProvider":null,"mark":"<svg width=\"24\" height=\"24\" viewBox=\"67 67 378 378\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"m415.348 156.575-151.504-87.4699c-4.865-2.8094-10.868-2.8094-15.733 0l-151.4964 87.4699c-4.0897 2.361-6.6146 6.728-6.6146 11.458v176.383c0 4.73 2.5249 9.097 6.6146 11.459l151.5034 87.469c4.865 2.81 10.868 2.81 15.733 0l151.504-87.469c4.09-2.362 6.615-6.729 6.615-11.459v-176.383c0-4.73-2.525-9.097-6.615-11.458zm-9.517 18.528-146.254 253.319c-.989 1.707-3.599 1.01-3.599-.967v-165.871c0-3.314-1.771-6.38-4.645-8.044l-143.644-82.932c-1.707-.989-1.01-3.599.967-3.599h292.51c4.153 0 6.749 4.502 4.672 8.101h-.007z\" fill=\"currentColor\"/></svg>","install":"curl https://cursor.com/install -fsS | bash","modelProvider":null,"terminal":true,"acp":true,"hosted":true,"sharedSessions":false}'
  WHEN 'gemini' THEN '{"label":"Gemini CLI","iconProvider":null,"mark":"<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n<path d=\"M12 2C12.6 7.2 16.8 11.4 22 12C16.8 12.6 12.6 16.8 12 22C11.4 16.8 7.2 12.6 2 12C7.2 11.4 11.4 7.2 12 2Z\" fill=\"currentColor\"/>\n</svg>","install":"npm install -g @google/gemini-cli","modelProvider":null,"terminal":true,"acp":false,"hosted":false,"sharedSessions":true}'
  WHEN 'opencode' THEN '{"label":"OpenCode","iconProvider":null,"mark":"<svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M6 4h12v16H6V4Zm3 3v10h6V7H9Z\" fill=\"currentColor\"/></svg>","install":null,"modelProvider":null,"terminal":true,"acp":true,"hosted":true,"sharedSessions":false}'
END))
WHERE json_valid(`facet`)
  AND json_type(`facet`, '$.presentation') IS NULL
  AND json_extract(`facet`, '$.name') IN ('claude-code', 'codex', 'grok', 'devin', 'cursor', 'gemini', 'opencode');
